module tb_TopModule;
    reg a;
    reg b;
    wire sum;
    wire cout;

    TopModule uut (
        .a(a),
        .b(b),
        .sum(sum),
        .cout(cout)
    );

    initial begin
        integer i;
        reg exp_sum, exp_cout;

        for (i = 0; i < 4; i = i + 1) begin
            {a, b} = i[1:0];
            #10;
            // Expected values derived independently:
            // sum = a ^ b
            // cout = a & b
            exp_sum = a ^ b;
            exp_cout = a & b;

            if (sum !== exp_sum || cout !== exp_cout) begin
                $display("SELFTEST FAIL: a=%b, b=%b => got sum=%b cout=%b, expected sum=%b cout=%b",
                         a, b, sum, cout, exp_sum, exp_cout);
                $finish;
            end
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
